 function detail(el){ const d=dish(S.open); if(!d){ S.open=null; return body(); } const r=S.recipe;
  el.innerHTML='<div class="rcDetail"><div class="rcBtns"><button type="button" data-rc="back">◀ Back</button></div><div class="rcHero" style="background:linear-gradient(135deg,'+d.col+',#2b1a0d)"><h3>'+COURSE[d.c][1]+' '+esc(d.name)+'</h3><p>'+d.flag+' '+esc(d.cul)+' · '+COURSE[d.c][0]+' · about '+TIME[d.c]+' min'+(d.veg?' · vegetarian':'')+'</p><p>Key ingredients: '+esc(d.ing)+'</p><p>'+d.meal.map(g=>lab(MEAL,g)).concat(d.gen.map(g=>lab(GEN,g)),d.ingr.map(g=>lab(ING,g)),d.meth.map(g=>lab(METH,g)),d.diet.map(g=>lab(DIET,g))).join(' · ')+'</p></div>'
   +'<div class="rcOpt">Servings '+[2,4,6,8,12,20].map(n=>'<button type="button" data-srv="'+n+'" class="'+(S.srv===n?'on':'')+'">'+n+'</button>').join('')+' · Units '+['US','Metric'].map(u=>'<button type="button" data-units="'+u+'" class="'+(S.units===u?'on':'')+'">'+u+'</button>').join('')+'</div>'
   +'<div class="rcBtns"><button type="button" class="go" data-rc="full">'+(r?'🔁 Write it again':'📖 Full recipe')+'</button><button type="button" data-rc="cook"'+(r?'':' disabled')+'>👨‍🍳 Cooking mode</button><button type="button" data-rc="fav">'+(S.fav.includes(d.id)?'⭐ Saved':'☆ Save')+'</button><button type="button" data-rc="shop"'+(r?'':' disabled')+'>🛒 Add to list</button><button type="button" data-rc="read"'+(r?'':' disabled')+'>🔊 Read it</button><a href="https://www.google.com/search?tbm=isch&q='+encodeURIComponent(d.name+' '+d.cul+' dish')+'" target="_blank" rel="noopener">📷 See photos</a><a href="https://www.google.com/search?q='+encodeURIComponent(d.name+' recipe')+'" target="_blank" rel="noopener">🔎 More recipes</a></div>'
   +'<div class="rcSec"><h4>Other ways to make it</h4><div class="rcOpt">'+WAYS.map(([k,l])=>'<button type="button" data-way="'+esc(k)+'" class="'+(S.way===k?'on':'')+'">'+l+'</button>').join('')+'</div></div>'
   +'<div id="rcOut">'+(S.busy?'<div class="rcSec"><p class="rcNote">The AI is writing the recipe…</p></div>':r?recipeHTML(r):'<div class="rcSec"><p class="rcNote">Tap 📖 Full recipe: the AI writes the ingredients and the steps for '+S.srv+' servings in '+S.units+' measures, and it stays saved on this device.</p></div>')+'</div>'+howTo(d)+'</div>'; }
 const recipeHTML=r=>'<div class="rcSec"><h4>'+esc(r.title||'')+'</h4><p class="rcNote">'+esc(r.summary||'')+'</p><p class="rcNote">⏱ prep '+(r.prep_minutes||'?')+' min · cook '+(r.cook_minutes||'?')+' min · '+esc(r.difficulty||'')+' · serves '+(r.servings||S.srv)+'</p></div>'+((r.equipment||[]).length?'<div class="rcSec"><h4>🍳 Equipment</h4><ul>'+r.equipment.map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul></div>':'')+'<div class="rcSec"><h4>🛒 Ingredients</h4><ul>'+(r.ingredients||[]).map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul></div><div class="rcSec"><h4>👨‍🍳 Steps</h4><ol>'+(r.steps||[]).map(s=>'<li>'+esc(s.text||s)+(s.minutes?' <b>(⏱ '+s.minutes+' min)</b>':'')+'</li>').join('')+'</ol></div>'+((r.tips||[]).length?'<div class="rcSec"><h4>💡 Tips</h4><ul>'+r.tips.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></div>':'')+((r.make_ahead||'')?'<div class="rcSec"><h4>🗓 Make ahead and storage</h4><p class="rcNote">'+esc(r.make_ahead)+'</p></div>':'');
 const rkey=d=>'kanin-rec-'+d.id+'-'+S.srv+'-'+S.units+'-'+(S.way||'');
 async function full(){ const d=dish(S.open); if(!sample){ el2('<div class="rcSec"><p class="rcNote">The AI writes full recipes for people signed in to claude.ai (and for everyone once KAN-IN runs on its own website). Meanwhile, 🔎 More recipes opens recipes on the web, and 🎓 How to cook it below teaches the method.</p></div>'); return; }
  S.busy=true; body(); const prompt='Write an authentic home-cook recipe for "'+d.name+'" from '+d.cul+' cuisine ('+COURSE[d.c][0]+'; key ingredients: '+d.ing+'). Serves '+S.srv+'. Use '+(S.units==='US'?'US cups, tablespoons, ounces and °F':'metric grams, millilitres and °C')+'.'+(S.way?' Adapt it: make it '+S.way+', and say what changes.':'')+' Include the safe internal temperature wherever meat, poultry, fish or eggs are cooked. Reply with JSON only: {"title":string,"summary":string (one or two sentences on the dish and its culture),"servings":number,"prep_minutes":number,"cook_minutes":number,"difficulty":"Easy"|"Medium"|"Hard","equipment":[string],"ingredients":[string],"steps":[{"text":string,"minutes":number|null}],"tips":[string],"make_ahead":string}. Steps in order, one action each, with minutes only where there is waiting or cooking time.';
  try{ const r=await sample.json(prompt,{modelTier:'default'}); if(r&&r.ingredients&&r.steps){ S.recipe=r; putLS(rkey(d),r); } else throw 0; }catch(e){ S.busy=false; el2('<div class="rcSec"><p class="rcNote">The recipe did not come through ('+esc((e&&e.code)||'try again')+'). Tap 📖 Full recipe again.</p></div>'); return; }
  S.busy=false; body(); }
