 function schoolHome(el){ el.innerHTML='<p class="rcNote">Every way to cook, every cut and its safe temperature, every grain’s ratio, every word a recipe uses, and how to plan a party. Tap a subject.</p><div class="rcTiles">'+SCH.map(s=>{ const n=(s.items||[]).length, t=['table','table2'].reduce((a,k)=>a+(s[k]?s[k].rows.length:0),0); return tile('school',s.id,s.i+' '+esc(s.t),esc(s.d)+'<br>'+(n?n+' lessons':'')+(n&&t?' · ':'')+(t?t+' table rows':''),'#25603a'); }).join('')+'</div>'; }
 const tableHTML=tb=>'<div class="rcTW"><table><caption>'+esc(tb.cap)+'</caption><thead><tr>'+tb.head.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+tb.rows.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const lkey=(sec,k)=>'kanin-school-'+sec+'-'+k;
 function lessonHTML(s,it,k){ const [t,f,st,tp,ln]=it; const steps=(st||'').split('|').filter(Boolean), tips=(tp||'').split('|').filter(Boolean); const ai=S.lesson[s.id+':'+k]||getLS(lkey(s.id,k),null);
  const all=fn=>D.filter(fn).length;
  let go=''; if(ln){ if(ln.meth) go='<button type="button" data-golink="meth:'+ln.meth+'">🍽 Dishes cooked this way ('+all(d=>d.meth.includes(ln.meth))+')</button>'; else if(ln.ing) go='<button type="button" data-golink="ingr:'+ln.ing+'">🍽 Dishes with it ('+all(d=>d.ingr.includes(ln.ing))+')</button>'; else if(ln.gen) go='<button type="button" data-golink="gen:'+ln.gen+'">🍽 Dishes ('+all(d=>d.gen.includes(ln.gen))+')</button>'; else if(ln.q) go='<button type="button" data-golink="q:'+esc(ln.q)+'">🍽 Dishes</button>'; }
  return '<details class="rcLes" id="les_'+s.id+'_'+k+'"><summary><b>'+esc(t)+'</b><small>'+esc(f)+'</small></summary><div>'+(steps.length?'<ol>'+steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>':'')+(tips.length?'<p class="rcNote" style="margin:4px 0 0"><b>💡 Tips</b></p><ul class="rcNote">'+tips.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')
   +(ai?'<div class="rcSec"><h4>🤖 '+esc(ai.title||t)+'</h4><p class="rcNote">'+esc(ai.overview||'')+'</p>'+((ai.steps||[]).length?'<ol>'+ai.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>':'')+((ai.mistakes||[]).length?'<p class="rcNote"><b>Common mistakes</b></p><ul class="rcNote">'+ai.mistakes.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+((ai.tips||[]).length?'<p class="rcNote"><b>More tips</b></p><ul class="rcNote">'+ai.tips.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+'</div>':'')
   +'<div class="rcOpt">'+go+'<button type="button" data-teach="'+s.id+':'+k+'">'+(ai?'🔁 Teach it again':'🤖 Teach me more')+'</button><button type="button" data-lessay="'+s.id+':'+k+'">🔊 Read it</button></div></div></details>'; }
 function schoolSec(el){ const s=SCH.find(x=>x.id===S.school); if(!s){ S.school=null; return schoolHome(el); } const I=s.items||[]; const defs=I.map((it,k)=>[it,k]).filter(([it])=>!it[2]&&!it[3]), full=I.map((it,k)=>[it,k]).filter(([it])=>it[2]||it[3]);
  el.innerHTML='<div class="rcDetail"><div class="rcBtns"><button type="button" data-rc="sback">◀ All subjects</button><button type="button" data-rc="sopen">▾ Open all</button></div><h3 class="rcH" style="font-size:22px">'+s.i+' '+esc(s.t)+'</h3><p class="rcNote">'+esc(s.d)+'</p>'
   +full.map(([it,k])=>lessonHTML(s,it,k)).join('')+(s.table?tableHTML(s.table):'')+(s.table2?tableHTML(s.table2):'')
   +(defs.length?'<h3 class="rcH">📖 '+defs.length+' words every recipe uses</h3><div class="rcDefs">'+defs.map(([it])=>'<div class="rcDef"><b>'+esc(it[0])+'</b>'+esc(it[1])+'</div>').join('')+'</div>':'')+'</div>'; }
 async function teach(id){ const [sec,k]=id.split(':'); const s=SCH.find(x=>x.id===sec); const it=s&&s.items[+k]; if(!it) return; if(!sample){ say('🤖 The AI teaches for people signed in to claude.ai.'); return; }
  say('🤖 Writing the lesson…'); try{ const r=await sample.json('Teach a home cook "'+it[0]+'" ('+it[1]+'). Be exact: temperatures in °F and °C, times, ratios. Reply with JSON only: {"title":string,"overview":string (two or three sentences),"steps":[string],"mistakes":[string],"tips":[string]}.',{modelTier:'default'}); if(r&&r.steps){ S.lesson[id]=r; putLS(lkey(sec,k),r); schoolSec($('rcBody')); const e=$('les_'+sec+'_'+k); if(e){ e.open=true; e.scrollIntoView({block:'start'}); } } else throw 0; }catch(_){ say('The lesson did not come through. Tap 🤖 Teach me more again.'); } }
 function goLesson(id){ const [sec,k]=id.split(':'); S.open=null; S.view='school'; S.school=sec; render(); setTimeout(()=>{ const e=$('les_'+sec+'_'+k); if(e){ e.open=true; e.scrollIntoView({block:'start'}); } else { const b=$('rcBody'); if(b) b.scrollTop=0; } },30); }
 function shop(el){ el.innerHTML='<div class="rcDetail"><div class="rcSec"><h4>🛒 Shopping list</h4>'+(S.list.length?'<ul style="list-style:none;padding:0">'+S.list.map((x,i)=>'<li><label style="display:flex;gap:8px;align-items:center;min-height:40px"><input type="checkbox" data-li="'+i+'"'+(x.done?' checked':'')+'> <span style="'+(x.done?'text-decoration:line-through;opacity:.6':'')+'">'+esc(x.t)+'</span> <small style="opacity:.6">· '+esc(x.from)+'</small></label></li>').join('')+'</ul>':'<p class="rcNote">Empty. Open a recipe and tap 🛒 Add to list.</p>')+'<div class="rcBtns"><button type="button" data-rc="copyl">📋 Copy the list</button><button type="button" data-rc="cleardone">Remove checked</button><button type="button" data-rc="clearall">Clear all</button></div></div></div>'; }
 let timer=null, wake=null;
 function cook(){ const r=S.recipe; if(!r) return; S.cook={i:0}; try{ navigator.wakeLock&&navigator.wakeLock.request('screen').then(w=>wake=w).catch(()=>{}); }catch(_){ } drawCook(); }
 function drawCook(){ let c=document.querySelector('#kRec .rcCook'); const r=S.recipe; const st=r.steps[S.cook.i]; const txt=st.text||st; if(!c){ c=document.createElement('div'); c.className='rcCook'; $('kRec').appendChild(c); }
  c.innerHTML='<div class="rcBtns" style="justify-content:space-between"><b style="font:900 16px system-ui;color:#ffc857">👨‍🍳 '+esc(r.title||'')+' · step '+(S.cook.i+1)+' of '+r.steps.length+'</b><button type="button" class="rcX" data-ck="x">✕</button></div><div class="st">'+esc(txt)+'</div><div class="tm" id="rcTm"></div><div class="nv"><button type="button" data-ck="prev"'+(S.cook.i?'':' disabled')+'>◀ Back</button><button type="button" data-ck="say">🔊 Read</button>'+(st.minutes?'<button type="button" data-ck="timer">⏱ '+st.minutes+' min timer</button>':'')+'<button type="button" data-ck="next" class="go" style="background:#ffc857!important;color:#2a1608!important">'+(S.cook.i<r.steps.length-1?'Next ▶':'Done ✓')+'</button></div>'; }
 function speak(t){ try{ speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(t); speechSynthesis.speak(u); }catch(_){ } }
 const clearAll=()=>{ FILT.forEach(k=>S[k]=null); };
 function pick(k,v){ S.open=null; S[k]=v; S.view='list'; S.lim=240; body(); const t=document.querySelectorAll('#kRec .rcTabs button'); t.forEach(b=>b.classList.remove('on')); }
 function onClick(e){ const t=e.target.closest('button,a,input,summary,select'); if(!t) return; if(t.tagName==='A'||t.tagName==='SUMMARY'||t.tagName==='SELECT') return; e.stopPropagation(); const ds=t.dataset;
  if(ds.tab){ S.open=null; S.school=null; S.lim=240; if(ds.tab==='fav'){ clearAll(); S.view='list'; S.gen='fav'; } else if(ds.tab==='list'){ S.view='shop'; } else { if(S.gen==='fav') S.gen=null; S.view=ds.tab; } render(); return; }
  if(ds.cul){ pick('cul',ds.cul); return; } if(ds.gen){ pick('gen',ds.gen); return; } if(ds.meth){ pick('meth',ds.meth); return; } if(ds.diet){ pick('diet',ds.diet); return; } if(ds.reg){ pick('reg',ds.reg); return; } if(ds.meal){ pick('meal',ds.meal); return; } if(ds.course){ pick('course',ds.course); return; } if(ds.size){ pick('size',ds.size); return; } if(ds.ingr){ pick('ingr',ds.ingr); return; } if(ds.sub){ S.sub=ds.sub; body(); return; }
  if(ds.school){ S.school=ds.school; S.view='school'; body(); return; }
  if(ds.les){ goLesson(ds.les); return; } if(ds.teach){ teach(ds.teach); return; }
  if(ds.lessay){ const [sec,k]=ds.lessay.split(':'); const s=SCH.find(x=>x.id===sec); const it=s&&s.items[+k]; if(it) speak(it[0]+'. '+it[1]+'. '+(it[2]||'').split('|').join('. ')+'. '+(it[3]||'').split('|').join('. ')); return; }
  if(ds.golink){ const i=ds.golink.indexOf(':'); const k=ds.golink.slice(0,i), v=ds.golink.slice(i+1); clearAll(); S.school=null; if(k==='q'){ S.q=v; S.view='list'; render(); } else { S.view='list'; S[k]=v; render(); } return; }
  if(ds.clr){ if(ds.clr==='all'){ clearAll(); S.school=null; } else if(ds.clr==='school'){ S.school=null; } else { S[ds.clr]=null; if(ds.clr==='gen') S.sub=null; } if(!FILT.some(k=>S[k])&&!S.q&&S.view==='list') S.view='cul'; render(); return; }
  if(ds.dish){ S.open=ds.dish; S.way=null; S.recipe=getLS(rkey(dish(S.open)),null); body(); return; }
  if(ds.srv){ S.srv=+ds.srv; putLS('kanin-rec-srv',S.srv); S.recipe=getLS(rkey(dish(S.open)),null); body(); return; } if(ds.units){ S.units=ds.units; putLS('kanin-rec-units',S.units); S.recipe=getLS(rkey(dish(S.open)),null); body(); return; }
  if(ds.way){ S.way=S.way===ds.way?null:ds.way; S.recipe=getLS(rkey(dish(S.open)),null); body(); if(!S.recipe) full(); return; }
  if(ds.li!=null){ const x=S.list[+ds.li]; if(x){ x.done=t.checked; putLS('kanin-rec-list',S.list); body(); } return; }
  if(ds.ck){ const r=S.recipe; if(ds.ck==='x'){ const c=document.querySelector('#kRec .rcCook'); if(c) c.remove(); S.cook=null; clearInterval(timer); try{ wake&&wake.release(); }catch(_){ } try{ speechSynthesis.cancel(); }catch(_){ } return; }
   if(ds.ck==='next'){ if(S.cook.i<r.steps.length-1){ S.cook.i++; drawCook(); } else { const c=document.querySelector('#kRec .rcCook'); if(c) c.remove(); say('🍽 Enjoy your '+(r.title||'dish')+'!'); } return; } if(ds.ck==='prev'){ S.cook.i=Math.max(0,S.cook.i-1); drawCook(); return; }
   if(ds.ck==='say'){ const st=r.steps[S.cook.i]; speak(st.text||st); return; } if(ds.ck==='timer'){ const st=r.steps[S.cook.i]; let left=st.minutes*60; clearInterval(timer); const tm=$('rcTm'); timer=setInterval(()=>{ left--; if(tm) tm.textContent='⏱ '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0'); if(left<=0){ clearInterval(timer); if(tm) tm.textContent='⏰ Time!'; speak('Time is up for this step.'); try{ navigator.vibrate&&navigator.vibrate([300,200,300]); }catch(_){ } } },1000); return; } return; }
  const a=ds.rc; if(!a) return; const d=S.open&&dish(S.open);
  if(a==='close'){ close(); return; } if(a==='back'){ S.open=null; body(); return; } if(a==='full'){ full(); return; } if(a==='cook'){ cook(); return; } if(a==='more'){ const y=$('rcBody').scrollTop; S.lim+=240; body(); $('rcBody').scrollTop=y; return; }
  if(a==='sback'){ S.school=null; body(); return; } if(a==='sopen'){ const all=[...document.querySelectorAll('#kRec .rcLes')]; const op=all.some(x=>!x.open); all.forEach(x=>x.open=op); t.textContent=op?'▴ Close all':'▾ Open all'; return; }
  if(a==='fav'){ const i=S.fav.indexOf(d.id); if(i>=0) S.fav.splice(i,1); else S.fav.push(d.id); putLS('kanin-rec-fav',S.fav); body(); return; }
  if(a==='shop'&&S.recipe){ (S.recipe.ingredients||[]).forEach(x=>S.list.push({t:x,from:d.name,done:false})); putLS('kanin-rec-list',S.list); say('🛒 '+(S.recipe.ingredients||[]).length+' ingredients added to your list.'); render(); S.open=d.id; body(); return; }
  if(a==='read'&&S.recipe){ speak((S.recipe.title||'')+'. Ingredients: '+(S.recipe.ingredients||[]).join(', ')+'. Steps: '+(S.recipe.steps||[]).map((s,i)=>(i+1)+'. '+(s.text||s)).join(' ')); return; }
  if(a==='copyl'){ const txt=S.list.map(x=>(x.done?'✓ ':'☐ ')+x.t).join('\n'); try{ navigator.clipboard.writeText(txt).then(()=>say('📋 Copied.'),()=>say('Select the list to copy it.')); }catch(_){ } return; }
  if(a==='cleardone'){ S.list=S.list.filter(x=>!x.done); putLS('kanin-rec-list',S.list); body(); return; } if(a==='clearall'){ S.list=[]; putLS('kanin-rec-list',S.list); body(); return; } }
 function open(q){ box().hidden=false; if(q){ S.q=q; S.view='list'; S.open=null; S.school=null; } render(); try{ LAUNCHPAD.fold(); }catch(_){ } }
 function school(sec){ box().hidden=false; S.open=null; S.q=''; S.view='school'; S.school=sec||null; render(); try{ LAUNCHPAD.fold(); }catch(_){ } }
 function close(){ const b=$('kRec'); if(b) b.hidden=true; try{ speechSynthesis.cancel(); }catch(_){ } }
 document.addEventListener('keydown',e=>{ const b=$('kRec'); if(e.key==='Escape'&&b&&!b.hidden){ const c=document.querySelector('#kRec .rcCook'); if(c){ c.remove(); } else if(S.open){ S.open=null; body(); } else if(S.school){ S.school=null; body(); } else close(); e.stopPropagation(); } },true);
