 const ML='🍳 Recipes · '+D.length.toLocaleString()+' dishes, '+NCUL+' cultures';
 setInterval(()=>{ const old=$('kdRec'); if(old) old.remove();
  const t=$('tourTab'); if(t&&!$('ttRec')){ const b=document.createElement('button'); b.type='button'; b.id='ttRec'; b.className='ttMusic kStartB'; b.textContent=ML; b.style.order='42'; b.setAttribute('data-noul',''); b.addEventListener('click',e=>{ e.stopPropagation(); setTimeout(()=>open(),120); }); t.appendChild(b); }
  if(t&&!$('ttSchool')){ const b=document.createElement('button'); b.type='button'; b.id='ttSchool'; b.className='ttMusic kStartB'; b.textContent='🎓 Cooking school · every method, cut, temperature and step'; b.style.order='42'; b.setAttribute('data-noul',''); b.addEventListener('click',e=>{ e.stopPropagation(); setTimeout(()=>school(),120); }); const r=$('ttRec'); if(r&&r.nextSibling) t.insertBefore(b,r.nextSibling); else t.appendChild(b); } },1000);
