 window.KREC={open,close,school,count:D.length,cultures:NCUL,collections:NCOLL,genres:GEN.map(g=>g[1]),diets:DIET.map(x=>x[1]),regions:REGIONS.map(r=>r[1]),meals:MEAL.map(x=>x[1]),ingredients:ING.map(x=>x[1]),methods:METH.map(x=>x[1]),dishes:()=>D,lessons:()=>LESSONS,goLesson:id=>{ box().hidden=false; goLesson(id); try{ LAUNCHPAD.fold(); }catch(_){ } }};
